/**
 * Why a call failed. Swift sees this as a thrown error.
 */
public 
enum CarrelError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The folder isn't inside a Carrel archive.
     */
    case NotAnArchive(
        /**
         * What was looked for, in plain words.
         */message: String
    )
    /**
     * Anything else, in plain words.
     */
    case Failed(
        /**
         * What went wrong.
         */message: String
    )
    /**
     * A Swift-implemented callback failed.
     */
    case Callback(
        /**
         * The callback's own description of what went wrong.
         */message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension CarrelError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCarrelError: FfiConverterRustBuffer {
    typealias SwiftType = CarrelError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CarrelError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotAnArchive(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Failed(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Callback(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CarrelError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .NotAnArchive(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Failed(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Callback(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


